<?php

/**
 * Error paths of cphalcon's base.c and %syntax_error: where the offending
 * token sits (first, middle, last byte), which token names and values are
 * printed, the 16-byte cut of scanning errors (driven by the *previous*
 * token's start_length), unknown opcodes, and statements cut short.
 */

declare(strict_types=1);

$rest = static fn (int $n): string => str_repeat('b', $n);

return [
    // position of the offending token
    'syntax first token'              => 'FROM r',
    'syntax first token value'        => 'r FROM r',
    'syntax middle'                   => 'SELECT * FROM r WHERE = 1',
    'syntax last byte'                => 'SELECT * FROM r WHERE a = =',
    'syntax last token then space'    => 'SELECT * FROM r WHERE a = = ',
    'syntax last token then newline'  => "SELECT * FROM r WHERE a = =\n",
    'syntax double statement'         => 'SELECT * FROM r SELECT * FROM r',
    'syntax trailing paren'           => 'SELECT * FROM r )',
    'syntax trailing comma'           => 'SELECT * FROM r,',
    'syntax trailing comma space'     => 'SELECT * FROM r, ',
    'syntax number start'             => '1',
    'syntax paren start'              => '(SELECT * FROM r)',
    'syntax unknown keyword'          => 'FOO BAR',

    // printed token names and values
    'value zero'                      => 'SELECT 0 0 FROM r',
    'value empty single string'       => "SELECT a '' FROM r",
    'value empty double string'       => 'SELECT a "" FROM r',
    'value string'                    => "SELECT a 'x y' FROM r",
    'value string with escapes'       => "SELECT a 'x\\ny' FROM r",
    'value identifier'                => 'SELECT a b c FROM r',
    'value bracket identifier'        => 'SELECT a b [c d] FROM r',
    'value double'                    => 'SELECT a 1.5 FROM r',
    'value hinteger'                  => 'SELECT a 0x1F FROM r',
    'value npl'                       => 'SELECT a ?0 FROM r',
    'value spl'                       => 'SELECT a :x: FROM r',
    'value bpl'                       => 'SELECT a {x} FROM r',
    'name true'                       => 'SELECT a TRUE FROM r',
    'name false'                      => 'SELECT a FALSE FROM r',
    'name null'                       => 'SELECT a NULL FROM r',
    'name not between'                => 'SELECT NOT BETWEEN FROM r',
    'name bitwise not'                => 'SELECT a ~ b FROM r',
    'name bitwise xor'                => 'SELECT ^ a FROM r',
    'name mod'                        => 'SELECT % a FROM r',
    'name every operator start'       => 'SELECT + FROM r',
    'name dot'                        => 'SELECT . a FROM r',
    'name json'                       => 'SELECT ->> a FROM r',
    'name pg'                         => 'SELECT @@ a FROM r',
    'name keyword'                    => 'SELECT WHERE FROM r',
    'name for'                        => 'SELECT * FROM r FOR',
    'name for select'                 => 'SELECT * FROM r FOR SELECT',
    'value near text with nul'        => "SELECT a b\0c FROM r",
    'value utf8 string'               => "SELECT 'ü' 'ü' FROM r",

    // statements cut short
    'eof select'                      => 'SELECT',
    'eof select star'                 => 'SELECT *',
    'eof select from'                 => 'SELECT * FROM',
    'eof where'                       => 'SELECT * FROM r WHERE',
    'eof where space'                 => 'SELECT * FROM r WHERE ',
    'eof binary'                      => 'SELECT * FROM r WHERE a +',
    'eof order'                       => 'SELECT * FROM r ORDER',
    'eof order by'                    => 'SELECT * FROM r ORDER BY',
    'eof insert'                      => 'INSERT',
    'eof insert into'                 => 'INSERT INTO r',
    'eof insert values'               => 'INSERT INTO r VALUES',
    'eof insert values paren'         => 'INSERT INTO r VALUES (',
    'eof update set'                  => 'UPDATE r SET',
    'eof update set item'             => 'UPDATE r SET a',
    'eof delete'                      => 'DELETE',
    'eof delete from where'           => 'DELETE FROM r WHERE',
    'eof fcall'                       => 'SELECT f(',
    'eof case'                        => 'SELECT CASE a WHEN 1 THEN 2',
    'eof cast'                        => 'SELECT CAST(a AS',

    // invalid constructs
    'is followed by literal'          => 'SELECT * FROM r WHERE a IS 1',
    'is not followed by literal'      => 'SELECT * FROM r WHERE a IS NOT 1',
    'limit identifier'                => 'SELECT * FROM r LIMIT a',
    'limit comma identifier'          => 'SELECT * FROM r LIMIT 1, a',
    'limit offset identifier'         => 'SELECT * FROM r LIMIT 1 OFFSET a',
    'limit twice'                     => 'SELECT * FROM r LIMIT 1 LIMIT 2',
    'offset without limit'            => 'SELECT * FROM r OFFSET 1',
    'update limit comma'              => 'UPDATE r SET a = 1 LIMIT 1, 2',
    'join without table'              => 'SELECT * FROM r JOIN',
    'join on without expr'            => 'SELECT * FROM r JOIN s ON',
    'left without join'               => 'SELECT * FROM r LEFT s',
    'outer join'                      => 'SELECT * FROM r OUTER JOIN s',
    'inner outer join'                => 'SELECT * FROM r INNER OUTER JOIN s',
    'cast literal type'               => 'SELECT CAST(a AS 1) FROM r',
    'cast without as'                 => 'SELECT CAST(a) FROM r',
    'convert with as'                 => 'SELECT CONVERT(a AS b) FROM r',
    'case without operand'            => 'SELECT CASE END FROM r',
    'case without when'               => 'SELECT CASE a END FROM r',
    'case when without then'          => 'SELECT CASE a WHEN 1 END FROM r',
    'fcall comma only'                => 'SELECT f(,) FROM r',
    'fcall trailing comma'            => 'SELECT f(a,) FROM r',
    'fcall distinct twice'            => 'SELECT f(DISTINCT DISTINCT a) FROM r',
    'qualified trailing dot'          => 'SELECT a. FROM r',
    'qualified three parts'           => 'SELECT a.b.c FROM r',
    'qualified dot star alias'        => 'SELECT a.* AS x FROM r',
    'star alias'                      => 'SELECT * AS x FROM r',
    'star in expr'                    => 'SELECT * + 1 FROM r',
    'in without parens'               => 'SELECT * FROM r WHERE a IN 1',
    'in subquery trailing'            => 'SELECT * FROM r WHERE a IN (SELECT b FROM s, )',
    'not in without parens'           => 'SELECT * FROM r WHERE a NOT IN 1',
    'exists without subquery'         => 'SELECT * FROM r WHERE EXISTS (1)',
    'subquery insert'                 => 'SELECT * FROM r WHERE a = (INSERT INTO s VALUES (1))',
    'from subquery'                   => 'SELECT * FROM (SELECT * FROM r)',
    'with without item'               => 'SELECT * FROM r WITH',
    'with empty list'                 => 'SELECT * FROM r WITH ()',
    'with qualified'                  => 'SELECT * FROM r WITH a.b',
    'insert empty values'             => 'INSERT INTO r VALUES ()',
    'insert empty fields'             => 'INSERT INTO r () VALUES (1)',
    'insert qualified field'          => 'INSERT INTO r (a.b) VALUES (1)',
    'insert star'                     => 'INSERT INTO r VALUES (*)',
    'insert select'                   => 'INSERT INTO r SELECT * FROM s',
    'update without set'              => 'UPDATE r WHERE a = 1',
    'update trailing comma'           => 'UPDATE r SET a = 1,',
    'update order by'                 => 'UPDATE r SET a = 1 ORDER BY a',
    'delete without from'             => 'DELETE r',
    'delete order by'                 => 'DELETE FROM r ORDER BY a',
    'delete star'                     => 'DELETE * FROM r',
    'group by empty'                  => 'SELECT * FROM r GROUP BY',
    'order by trailing comma'         => 'SELECT * FROM r ORDER BY a,',
    'order by asc asc'                => 'SELECT * FROM r ORDER BY a ASC ASC',
    'between without and'             => 'SELECT * FROM r WHERE a BETWEEN 1',
    'not alone in where'              => 'SELECT * FROM r WHERE NOT',
    'double not between'              => 'SELECT * FROM r WHERE a NOT NOT BETWEEN 1 AND 2',

    // scanning errors: 16-byte cut uses the previous token's start_length
    'scan first byte short'           => "\x01 abc",
    'scan first byte long'            => "\x01" . $rest(30),
    'scan remaining 15'               => "SELECT a\x01" . $rest(14),
    'scan remaining 16'               => "SELECT a\x01" . $rest(15),
    'scan remaining 17'               => "SELECT a\x01" . $rest(16),
    'scan remaining 18'               => "SELECT a\x01" . $rest(17),
    'scan after whitespace 16'        => "SELECT a \x01" . $rest(15),
    'scan after whitespace 17'        => "SELECT a \x01" . $rest(16),
    'scan last byte'                  => "SELECT a\x01",
    'scan utf8 split'                 => "SELECT a\x01" . 'aéééééééé',
    'scan utf8 lead byte'             => 'SELECT ü FROM r',
    'scan string unterminated short'  => "SELECT 'abc",
    'scan string unterminated long'   => "SELECT 'abcdefghijklmnopqrstuvwxyz",
    'scan string trailing backslash'  => "SELECT * FROM r WHERE a = 'abc\\'",
    'scan bracket unterminated long'  => 'SELECT [abcdefghijklmnopqrstuvwxyz',
    'scan hash'                       => 'SELECT # FROM r',
    'scan at'                         => 'SELECT @ FROM r',
    'scan bang'                       => 'SELECT ! FROM r',
    'scan semicolon'                  => 'SELECT * FROM r; DELETE FROM r',
    'scan after syntax error'         => "SELECT a b \x01",
    'scan before syntax error'        => "SELECT \x01 a b",
    'unknown opcode colon'            => 'SELECT : FROM r',
    'unknown opcode colon at start'   => ':',
    'unknown opcode after error'      => 'SELECT a b :',

    // literals interplay (also run with literals disabled by the harness)
    'literal then syntax error'       => 'SELECT 1 2 FROM r',
    'literal after syntax error'      => 'SELECT a b 1 FROM r',
    'literal then scan error'         => "SELECT 1 \x01",
    'literal in limit'                => 'SELECT * FROM r LIMIT 10',
    'literal true in where'           => 'SELECT * FROM r WHERE a = TRUE',
    'literal null in where'           => 'SELECT * FROM r WHERE a = NULL',
    'placeholders only'               => 'SELECT * FROM r WHERE a = :a: LIMIT :l:',
];
